template <int N>
__global__ void packed_cholesky_kernel(
    const float* __restrict__ input,
    float* __restrict__ output) {
    extern __shared__ float factor[];
    const int lane = threadIdx.x;
    const int matrix = blockIdx.x;
    const float* source = input + static_cast<size_t>(matrix) * N * N;
    float* result = output + static_cast<size_t>(matrix) * N * N;

    // Keep only the lower triangle in shared memory.  The packed layout lets
    // even N=256 fit in one block's opt-in shared-memory allocation.
    for (int row = 0; row < N; ++row) {
        if (lane <= row) {
            factor[row * (row + 1) / 2 + lane] = source[row * N + lane];
        }
    }
    block_barrier<N>();

    // Seed the first pivot, then let the row immediately below each column
    // produce the next pivot after its solve.  One barrier publishes both.
    if (lane == 0) {
        factor[0] = sqrtf(fmaxf(factor[0], 1.0e-20f));
    }
    block_barrier<N>();
    for (int column = 0; column < N; ++column) {
        if (lane > column) {
            const int row_base = lane * (lane + 1) / 2;
            const int column_base = column * (column + 1) / 2;
            float value = factor[row_base + column];
#pragma unroll 4
            for (int k = 0; k < column; ++k) {
                value = fmaf(-factor[row_base + k], factor[column_base + k], value);
            }
            factor[row_base + column] =
                value / factor[column_base + column];

            if (lane == column + 1) {
                float diagonal = factor[row_base + lane];
#pragma unroll 4
                for (int k = 0; k <= column; ++k) {
                    const float factor_value = factor[row_base + k];
                    diagonal = fmaf(-factor_value, factor_value, diagonal);
                }
                factor[row_base + lane] = sqrtf(fmaxf(diagonal, 1.0e-20f));
            }
        }
        if (column + 1 < N) {
            block_barrier<N>();
        }
    }

    // Coalesced dense writeback also explicitly clears the upper triangle.
    for (int row = 0; row < N; ++row) {
        result[row * N + lane] =
            lane <= row ? factor[row * (row + 1) / 2 + lane] : 0.0f;
    }
}

template <int WIDTH>
__device__ __forceinline__ float subgroup_sum(float value) {
    const unsigned mask = __activemask();
#pragma unroll
    for (int offset = WIDTH / 2; offset > 0; offset >>= 1) {
        value += __shfl_down_sync(mask, value, offset, WIDTH);
    }
    return value;
}

template <int N, int ROW_THREADS>
__global__ void cooperative_cholesky_kernel(
    const float* __restrict__ input,
    float* __restrict__ output) {
    extern __shared__ float factor[];
    const int worker = threadIdx.x;
    const int row = worker / ROW_THREADS;
    const int part = worker % ROW_THREADS;
    const int matrix = blockIdx.x;
    const float* source = input + static_cast<size_t>(matrix) * N * N;
    float* result = output + static_cast<size_t>(matrix) * N * N;

    for (int index = worker; index < N * N; index += blockDim.x) {
        const int source_row = index / N;
        const int column = index - source_row * N;
        if (column <= source_row) {
            factor[source_row * (source_row + 1) / 2 + column] = source[index];
        }
    }
    __syncthreads();

    // Seed the first pivot, then compute each next pivot in the same row team
    // that finishes the preceding column.  This needs one block barrier per
    // column instead of separate pivot and solve barriers.
    if (row == 0 && part == 0) {
        factor[0] = sqrtf(fmaxf(factor[0], 1.0e-20f));
    }
    __syncthreads();
    for (int column = 0; column < N; ++column) {
        if (row > column) {
            const int row_base = row * (row + 1) / 2;
            const int column_base = column * (column + 1) / 2;
            float product_sum = 0.0f;
            for (int k = part; k < column; k += ROW_THREADS) {
                product_sum = fmaf(
                    factor[row_base + k], factor[column_base + k], product_sum);
            }
            product_sum = subgroup_sum<ROW_THREADS>(product_sum);
            float solved = 0.0f;
            if (part == 0) {
                solved =
                    (factor[row_base + column] - product_sum) /
                    factor[column_base + column];
                factor[row_base + column] = solved;
            }
            solved = __shfl_sync(__activemask(), solved, 0, ROW_THREADS);

            if (row == column + 1) {
                float square_sum = part == 0 ? solved * solved : 0.0f;
                for (int k = part; k < column; k += ROW_THREADS) {
                    const float value = factor[row_base + k];
                    square_sum = fmaf(value, value, square_sum);
                }
                square_sum = subgroup_sum<ROW_THREADS>(square_sum);
                if (part == 0) {
