@cuda.jit
def _d256_potrf_three_cta(source, destination, flags, epoch):
    sample = cuda.blockIdx.x // 3
    worker = cuda.blockIdx.x - sample * 3
    sample_base = sample * _D256_MATRIX_ELEMENTS
    marker_index = sample * 2
    arrival_index = marker_index + 1
    shared = cuda.shared.array(shape=0, dtype=np.float32, alignment=16)
    a_shared = shared[0:_D256_TILE_ELEMENTS]
    b_shared = shared[_D256_TILE_ELEMENTS : 2 * _D256_TILE_ELEMENTS]
    update_shared = shared[
        2 * _D256_TILE_ELEMENTS : 3 * _D256_TILE_ELEMENTS
    ].view(np.float16)
    c_shared = update_shared[0:_D256_TILE_ELEMENTS]
    d_shared = update_shared[
        _D256_TILE_ELEMENTS : 2 * _D256_TILE_ELEMENTS
    ]
    local_info = shared[3 * _D256_TILE_ELEMENTS :].view(np.int32)

    tile_count = _D256_N // _D256_NB
    if worker == 0 and cuda.threadIdx.x == 0:
        cuda.atomic.exch(flags, arrival_index, 0)
    for k in range(tile_count):
        if worker == 0:
            if k == 0:
                _d256_load_diagonal(source, sample_base, k, a_shared)
            else:
                _d256_load_first_diagonal_update(
                    source,
                    destination,
                    sample_base,
                    k,
                    a_shared,
                    c_shared,
                )
                _d256_gemm.execute(
                    -1.0, c_shared, c_shared, 1.0, a_shared
                )
                cuda.syncthreads()
            for i in range(1, k):
                _d256_load_tile(
                    destination, sample_base, i, k, c_shared
                )
                _d256_gemm.execute(
                    -1.0, c_shared, c_shared, 1.0, a_shared
                )
                cuda.syncthreads()
            _d256_cholesky.factorize(
                a_shared, local_info, lda=_D256_NB
            )
            _d256_store_tile(
                a_shared, destination, sample_base, k, k, True
            )
        cuda.syncthreads()
        token = epoch * tile_count + k + 1
        if cuda.threadIdx.x == 0:
            if worker == 0:
                cuda.threadfence()
                cuda.atomic.exch(flags, marker_index, token)
            else:
                while cuda.atomic.add(flags, marker_index, 0) != token:
                    pass
        cuda.syncthreads()

        if k + 1 < tile_count:
            has_panel = k + 1 + worker < tile_count
            if worker != 0 and has_panel:
                _d256_load_tile(
                    destination, sample_base, k, k, a_shared
                )
            for j in range(k + 1 + worker, tile_count, 3):
                if k == 0:
                    _d256_load_tile(
                        source, sample_base, k, j, b_shared
                    )
                else:
                    _d256_load_first_panel_update(
                        source,
                        destination,
                        sample_base,
                        k,
                        j,
                        b_shared,
                        c_shared,
                        d_shared,
                    )
                    _d256_gemm.execute(
                        -1.0, c_shared, d_shared, 1.0, b_shared
                    )
                    cuda.syncthreads()
                for i in range(1, k):
                    _d256_load_tile_pair(
                        destination,
                        sample_base,
                        i,
                        k,
                        c_shared,
                        j,
                        d_shared,
                    )
                    _d256_gemm.execute(
                        -1.0, c_shared, d_shared, 1.0, b_shared
                    )
                    cuda.syncthreads()
                _d256_triangular.solve(
                    a_shared, b_shared, lda=_D256_NB, ldb=_D256_NB
                )
                _d256_store_tile(
                    b_shared, destination, sample_base, k, j, False
                )
            if has_panel:
                cuda.syncthreads()
                cuda.threadfence()
                if cuda.threadIdx.x == 0:
                    cuda.atomic.add(flags, arrival_index, 1)
            cuda.syncthreads()
            target = (k + 1) * 3 - (k * (k + 1)) // 2
            if cuda.threadIdx.x == 0 and worker == 0:
                while cuda.atomic.add(flags, arrival_index, 0) < target:
                    pass
            cuda.syncthreads()


def _launch_d256(data_view, output_view, flag_view, epoch, batch):
    global _d256_dispatch, _d256_queue_handle, _d256_queue
    if _d256_dispatch is None:
        _d256_dispatch = _d256_potrf_three_cta.specialize(
            data_view, output_view, flag_view, epoch
        )
        compiled = next(iter(_d256_dispatch.overloads.values()))
        function = compiled._codelibrary.get_cufunc()
        attribute = (
            cuda_driver.CUfunction_attribute.
            CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES
        )
        numba_driver.driver.cuKernelSetAttribute(
            attribute,
            _D256_SHARED_BYTES,
            function.handle,
            function.device.id,
        )
    torch_queue = _torch_current_queue()
    queue_handle = getattr(torch_queue, _torch_queue_handle_name)
    if queue_handle != _d256_queue_handle:
        _d256_queue = _external_queue(queue_handle)
        _d256_queue_handle = queue_handle
    _d256_dispatch[
        batch * 3, _D256_NT, _d256_queue, _D256_SHARED_BYTES
    ](
        data_view, output_view, flag_view, epoch
    )


_d256_output_cache = {}
_d256_last_input = None
_d256_last_entry = None
_d256_epoch = 0


def _run_d256(data: torch.Tensor) -> torch.Tensor:
    global _d256_last_input, _d256_last_entry, _d256_epoch
    if _d256_last_input is data:
        entry = _d256_last_entry
    else:
        key = id(data)
        entry = _d256_output_cache.get(key)
        if entry is None or entry[0] is not data:
            output = torch.zeros_like(
                data, memory_format=torch.contiguous_format
            )
            flags = torch.empty(
                data.shape[0] * 2,
                device=data.device,
                dtype=torch.int32,
            )
            entry = (
                data,
                output,
                _as_numba_flat_array(data),
                _as_numba_flat_array(output),
                flags,
                _as_numba_flat_array(flags),
            )
            _d256_output_cache[key] = entry
        _d256_last_input = data
        _d256_last_entry = entry
    _d256_epoch += 1
    _launch_d256(
        entry[2], entry[3], entry[5], np.int32(_d256_epoch), data.shape[0]
    )
    return entry[1].transpose(-2, -1)


_output_cache = {}
_info = None
_workspace = None
_half_workspace = None
_factor_workspace = None
_factor_info = None
_dx_dispatch = None

